Algorithm CuentaRegresiva
  Define n As Integer <- 3;
  While n > 0 Do
    Write n;
    n <- n - 1;
  EndWhile
  Write "¡Ya!";
EndAlgorithm

Algorithm Alcancia
  Define dia As Integer <- 1;
  Define guardaHoy As Integer <- 2;
  Define ahorro As Integer <- 2;
  While ahorro < 50 Do
    dia <- dia + 1;
    guardaHoy <- guardaHoy + 1;
    ahorro <- ahorro + guardaHoy;
  EndWhile
  Write "Lucía compra la pelota el día ", dia, " con ", ahorro, " monedas";
EndAlgorithm

Algorithm Alcancia
  Define precio As Integer;
  Read precio;
  Define dia As Integer <- 1;
  Define guardaHoy As Integer <- 2;
  Define ahorro As Integer <- 2;
  While ahorro < precio Do
    dia <- dia + 1;
    guardaHoy <- guardaHoy + 1;
    ahorro <- ahorro + guardaHoy;
  EndWhile
  Write "Día ", dia, " con ", ahorro, " monedas";
EndAlgorithm

Algorithm Infinito
  Define ahorro As Integer <- 2;
  Define guardaHoy As Integer <- 2;
  While ahorro < 50 Do
    guardaHoy <- guardaHoy + 1;
  EndWhile
  Write ahorro;
EndAlgorithm

Algorithm AlcanciaDictada
  Define monedas As Integer;
  Define ahorro As Integer <- 0;
  Read monedas;
  While monedas <> -1 Do
    ahorro <- ahorro + monedas;
    Read monedas;
  EndWhile
  Write "Juntó ", ahorro, " monedas";
EndAlgorithm
